var lincloud_langpac={"en":{"repl-0001":"Link Collection",},"ja":{"repl-0001":"リンク集",}};function lincloud_init(config){var token=config.lincloud_token;var node=document.getElementById(config.node);fetch("https://cdn.jsdelivr.net/gh/htvoffcial/lincloud@production/userdata/lincloud.json").then(response=>response.json()).then(data=>{var content=data[token];if(!content){node.innerHTML="Invalid token.";return;}var lang=navigator.language.startsWith("ja")?"ja":"en";var repl_0001=lincloud_langpac[lang]["repl-0001"]||lincloud_langpac["en"]["repl-0001"];var html=`<div class="lincloud"><div class="lincloud-header"><img src="${content.usericonpath}" alt="${content.username}"><p>${content.username}</p></div><div class="lincloud-content"><h3>${repl_0001}</h3><div class="lincloud-linclist">`;for(var i=0;i<content["list-linkurl"].length;i++){html+=`<a href="${content["list-linkurl"][i]}">${content["linktitle"][i]}</a>`;}html+=`</div></div><div class="lincloud-footer"><p>${content.postedtime}Powered by LinCloud</p></div></div><style>.lincloud{box-sizing:border-box;font-family:ヒラギノ角ゴ Pro,Noto Sans JP,sans-serif;box-shadow:0 2px 5px rgba(0,0,0,.1);border-radius:5px;width:100%;max-width:400px;}.lincloud-header{display:flex;align-items:center;gap:10px;background-color:#003368ee;border-radius:5px 5px 0 0;padding:10px}.lincloud-header img{width:20px;height:20px;border-radius:50%}.lincloud-header p{margin:0;font-size:13px;color:#e9e9e9}.lincloud-content h3{margin:10px 0 0 10px;font-size:13px;color:#555}.lincloud-linclist{padding:10px;display:flex;flex-direction:column}.lincloud-linclist a{display:flex;color:#664e21;font-weight:700;text-decoration:none;margin-bottom:5px;font-size:13px;align-items:center;gap:5px}.lincloud-linclist a::after{display:block;content:" ";width:15px;height:13px;background:url(data:image/svg+xml;base64,) no-repeat center center;background-size:contain}.lincloud-linclist a:hover{text-decoration:underline}.lincloud-footer{font-size:12px;color:#777;margin-top:10px;padding:10px}.lincloud-footer p{margin:0}</style>`;node.innerHTML=html;}).catch(error=>{node.innerHTML="Error loading LinCloud content.";console.error(error);});}
